CREATE INDEX ix_family_member_active_parent_family ON family_member (parent_id, family_id) WHERE active = true;
CREATE INDEX ix_child_profile_family ON child_profile (family_id, id);
CREATE INDEX ix_pairing_code_active_child_expiry ON pairing_code (child_profile_id, expires_at) WHERE used_at IS NULL;
CREATE INDEX ix_device_credential_active_hash_expiry ON device_credential (credential_hash, expires_at) WHERE revoked_at IS NULL;
CREATE INDEX ix_security_audit_family_time ON security_audit_event (family_id, occurred_at);

rollback.sql:
DROP INDEX IF EXISTS ix_security_audit_family_time;
DROP INDEX IF EXISTS ix_device_credential_active_hash_expiry;
DROP INDEX IF EXISTS ix_pairing_code_active_child_expiry;
DROP INDEX IF EXISTS ix_child_profile_family;
